l beneath","commission":"dormant","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Punta Jesús María sandbar","si_tag":"expedition","tier":"essential","source":"https://ometepenicaragua.com/charcoverde/index.php","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"long sandbar spit reaching into the lake, framed views of both volcanoes; classic sunset point. price","si":"expedition","blurb":"long sandbar spit reaching into the lake, framed views of both volcanoes; classic sunset point. price","when":"Dry season Dec–Apr","commission":"dormant","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Ojo de Agua natural spring","si_tag":"wellness","tier":"essential","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"underground-fed mineral swimming holes between the volcanoes; the island''s slow-morning ritual. price","si":"wellness","blurb":"underground-fed mineral swimming holes between the volcanoes; the island''s slow-morning ritual. price","when":"Dry season Dec–Apr","commission":"dormant","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["wellness"],"shelf_fit":{"wellness":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Charco Verde Nature Reserve","si_tag":"wellness","tier":"essential","source":"https://travelmademedoit.com/charco-verde-ometepe/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"algae-green lagoon and lake beaches on Concepción''s south side, with the Mirador del Diablo lookout above. price","si":"wellness","blurb":"algae-green lagoon and lake beaches on Concepción''s south side, with the Mirador del Diablo lookout above. price","when":"Dry season Dec–Apr","commission":"dormant","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["wellness"],"shelf_fit":{"wellness":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Pre-Columbian petroglyphs (1,700+)","si_tag":"Culture/Romance","tier":"essential","source":"https://www.dreambigtravelfarblog.com/blog/ometepe-nicaragua","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"1,700+ carvings across 100+ sites; densest at Finca Magdalena; half-submerged carved stones near Tichana past San Ramón. price","si":"romance","blurb":"1,700+ carvings across 100+ sites; densest at Finca Magdalena; half-submerged carved stones near Tichana past San Ramón. price","when":"Dry season Dec–Apr","commission":"dormant","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["Culture/Romance","culture","romance"],"shelf_fit":{"Culture/Romance":"evidenced","culture":"evidenced","romance":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Culture/Romance","si_map_basis":"normalised from free text ''Culture/Romance'' by gen_normalise_jewel_si"}],"faq":[{"q":"What makes Ometepe Island special?","a":"Ometepe is the largest island in a freshwater lake in the world and a UNESCO Biosphere Reserve since 2010, formed by two volcanoes — active Concepción (1,610 m) and dormant Maderas (1,394 m) — joined by the Isthmus of Istián across roughly 276 km². It also holds over 1,700 pre-Columbian petroglyphs across more than 100 documented sites.","source":"en.unesco.org; lacgeo.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"How hard are the Ometepe volcano hikes?","a":"Both are serious. Concepción is a strenuous ~10-hour dawn-start climb; Maderas is ~8 hours via a ~4.5 km trail from Balgüe / Finca Magdalena, with a crater lagoon you can swim in at the summit. A licensed local guide is mandatory for both because the upper slopes are exposed, muddy, and cloud-forest-slick.","source":"ometepenicaragua.com; alongdustyroads.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where can you swim on Ometepe?","a":"Ojo de Agua (\"eye of the water\") is the island''s signature spot — a natural mineral swimming hole fed by an underground river originating on Volcán Maderas, about 2 km from Santo Domingo. Go early or late to avoid crowds. Maderas'' summit crater lagoon and designated lake beaches are the other locally advised swims.","source":"ometepenicaragua.com, Accessed 2026-07-07","si_tag":"wellness"},{"q":"Where do couples stay on Ometepe?","a":"Ometepe skews to off-grid eco-lodges rather than resorts. Totoco Eco-Lodge (8 design cabins on Maderas'' slopes, lake-and-Concepción views, farm-to-table dining), Finca del Sol (a 100% sustainable eco-lodge with permaculture farm), and Hacienda Mérida give the quiet, unscripted, two-people-and-a-volcano energy.","source":"steppestravel.com; hotelfincadelsol.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the real risk to plan for?","a":"Two things: political detention and remoteness. And there is no trauma-grade care on-island — comprehensive care exists only in Managua, so a serious case realistically means Managua then a US medical evacuation.","source":"https://www.gov.uk/foreign-travel-advice/nicaragua","si_tag":"safety"},{"q":"Is climbing an active volcano here dangerous?","a":"Concepción is an active stratovolcano (its last significant ash event was March 2010), and its summit hike is strenuous, exposed, and dawn-started; Maderas is dormant but steep, muddy, and cloud-forest-slick.","source":"ometepenicaragua.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"jsonld_type":"TouristDestination","search_language":"es-NI","local_keywords":["Isla de Ometepe qué hacer","Volcán Concepción","Volcán Maderas laguna cráter","Ojo de Agua Ometepe","cascada San Ramón Ometepe","kayak Río Istián","petroglifos Ometepe","ferry San Jorge Ometepe"],"hreflang":["en","es-NI"],"primary_keyword":"Ometepe Island","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/nicaragua","read":"2026-08-20T14:55:16Z","source_updated":"2025-12-10T13:20:42+00:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"wellness","status":"live"}],"ultra":[{"name":"Totoco Eco-Lodge","location":"Balgüe","price_tier":"mid/boutique-eco","commission_path":"dormant","source":"https://www.steppestravel.com/accommodation/totoco-eco-lodge/"},{"name":"Finca del Sol Eco Lodge","location":"Maderas base","price_tier":"mid/eco","commission_path":"dormant","source":"https://hotelfincadelsol.com/"},{"name":"Hacienda Mérida","location":"Mérida","price_tier":"value/mid","commission_path":"dormant","source":"https://www.hmerida.com/espanol/activity/1"}],"source_verified":null,"hero":{"query":"Ometepe Island, Nicaragua, Nicaragua"},"geo":{"lat":11.5,"lng":-85.5833},"orbit":[{"id":"granada-nicaragua","jewels":7,"si":["culture"]},{"id":"san-juan-del-sur-nicaragua","jewels":7,"si":["tropical","romance"]}],"orbit_country":[]}'::jsonb, 75),
