  ('paracas-nazca-peru', '10S', 'Paracas, Nazca & the South Coast', 'Peru', '*If it''s a desert oasis, a "poor man''s Galápagos,"', 'live', 'verified', 'desertDunes', 'Lima, South Coast & Amazon', '{"expedition","culture","culinary"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["The South Coast is a desert-and-ocean circuit ~3–4 hr south of Lima on the Panamericana Sur — no altitude, no cloud-forest; the risks are activity/operator, not crime.","Ballestas Islands (''poor man''s Galápagos'') — sea lions, Humboldt penguins, boobies, 150+ bird species — visitable only by ~2-hr guided boat from El Chaco pier.","Nazca Lines are best seen on a ~30–35 min light-aircraft overflight from María Reiche Neuman aerodrome (NZC) — choose a reputable operator (accident history; 2022 fatal crash) and expect banking-turn motion sickness.","Huacachina is a real palm-ringed desert oasis outside Ica; the marquee is the sunset dune-buggy + sandboard circuit — ride only permitted buggies (four-point belts + roll cages).","Paracas National Reserve (~S/11 entry) has Playa Roja (Red Beach) and La Catedral; swimming is prohibited at Playa Roja (open swell, strong currents, no lifeguards)."],"safety":{"emergency":"105","emergency_ambulance":"117","emergency_fire":"116","tourist_line":"iPerú / Policía de Turismo","hospital":"Ica & Pisco clinics for routine/stabilization; serious cases evac to Lima (Clínica Anglo Americana / Ricardo Palma); desert stretches remote","book_enabled":true,"air_access_verified":true,"air_access_note":"Fly Lima (LIM); road ~3–4 hr south on the Panamericana Sur to Paracas/Ica; Nazca overflights depart María Reiche Neuman aerodrome (NZC)","activity_flags":{"nazca_overflight":"reputable/authorized operator only (accident history; 2022 fatal crash); small-plane turbulence + motion sickness; weather-suspension risk (wind/dust/garua)","huacachina_dune_buggy":"rollover risk; permitted operators only (four-point belts, roll cages, headrests, certified welds, <=15-yr vehicles); avoid informal ''tubular'' buggies","ballestas_boat":"open-ocean swell; life vests provided and worn","pacific_coast":"riptides, strong currents, no lifeguards; Playa Roja swimming prohibited; railing-less cliffs at La Catedral","wind_sport":"May–Sep kitesurf — school + PFD, offshore-wind hazard"},"sun":"high desert UV — sunscreen, hats, hydration","water":"bottled/purified only","malaria":"none on the arid South Coast (malaria risk is the low-elevation Amazon)","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/peru","read":"2026-08-20T14:53:51Z","page_updated":"2026-06-22T23:35:12+01:00","source_country":"peru","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"fcdo_zones":[{"name":"The VRAEM (Apurimac, Ene and Mantaro valley)","lvl":4},{"name":"The Colombia-border area of Loreto","lvl":4}]},"timing":{"peak":"December–April (Peruvian summer, hot/sunny; beach + desert; Paracas year-round as Lima escape)","event_peak":"Ica Vendimia grape-harvest festival — first weeks of March","inflection_curve_start":"summer: late Oct–early Nov; Vendimia: mid-to-late January","fire_date":"2026-10-20 (summer peak) / 2026-01-15 (Vendimia) — each = curve-start − 1–2 weeks","wind_sport_window":"May–September (winter; stronger Paracas winds; kitesurf; clearer Nazca skies but garua/gust flight-suspension risk)","shoulder":"April–May & October–November (best value)","booking_lead":"core circuit days–weeks; Huacachina sunset/weekend buggy 2–3 days; Vendimia + Dec–Apr Paracas resorts weeks–months","event_peaks":["Ica Vendimia (grape-harvest festival), March"],"off_season_specials":"winter wind-sport + shoulder value stays + year-round Lima day-trip/overnight bundles"},"jewels":[{"name":"Ballestas Islands (''poor man''s Galápagos'')","si_tag":"GEA","status":"live","hook":"Sea lions, Humboldt penguins, boobies & 150+ bird species under guano cliffs — 20 