diving.com/en/activities/diving-in-the-sea/puerto-morelos-reef-shipwreck-diving/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"sunken boat now an artificial reef and fish refuge","when":"Dec-Apr","commission":"local dive-op → OTA affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","ocean"],"shelf_fit":{"adventure":"destination","culinary":"destination","diveglobal":"primary","ocean":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Puerto Morelos Reef National Park snorkel","si_tag":"ocean","status":"future","tier":"essential","hook":"living reef under 500 m offshore, turtles/rays/lobster","bookable_category":"guided reef snorkel/dive","source":"https://voyage-mexico.com/en/puerto-morelos.html","si":"ocean","blurb":"living reef under 500 m offshore, turtles/rays/lobster","commission":"local operator → OTA (park fee pass-through)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","ocean"],"shelf_fit":{"adventure":"destination","culinary":"destination","diveglobal":"evidenced","ocean":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Deep-sea fishing charter","si_tag":"ocean","status":"future","tier":"premier","hook":"half/full-day for dorado, wahoo, tuna, barracuda","bookable_category":"private/shared charter","source":"https://voyage-mexico.com/en/puerto-morelos.html","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"half/full-day for dorado, wahoo, tuna, barracuda","when":"Dec-Apr","commission":"local charter operator → curated-recommend","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["ocean"],"shelf_fit":{"adventure":"destination","culinary":"destination","diveglobal":"destination","oce